.staging-shell{max-width:1120px;margin:auto;padding:28px;color:#f0eee7}.staging-header{display:flex;gap:20px;align-items:center;flex-wrap:wrap;border-bottom:1px solid #474940;padding-bottom:18px}.staging-header a{font-size:1.6rem;font-weight:650;color:inherit;text-decoration:none}.staging-header span{color:#c1c8b7}.staging-header button{margin-left:auto}.staging-notice{padding:16px;border:1px solid #53614c;border-radius:12px;background:#1d261b;line-height:1.6}.staging-signin{max-width:440px;margin:64px auto;padding:30px;border:1px solid #44473e;border-radius:18px;background:#171b16}.staging-signin h1{font-size:2rem;margin-bottom:12px}.staging-signin p{line-height:1.6;color:#c9cebf}.staging-signin form{display:grid;gap:18px;margin:24px 0}.staging-signin label{display:grid;gap:8px}.staging-signin input{padding:12px;border:1px solid #626958;border-radius:8px;background:#10140f;color:#fff;font:inherit}.staging-shell button{min-height:44px}.staging-signin button,.staging-header button{padding:10px 20px;background:#b8d997;border:0;border-radius:8px;color:#19200f;font:inherit;font-weight:600;cursor:pointer}.staging-signin button:disabled,.staging-header button:disabled{opacity:.5;cursor:wait}.staging-shell :focus-visible{outline:3px solid #d8ecaf;outline-offset:4px}@media(max-width:600px){.staging-shell{padding:18px}.staging-signin{margin:28px auto;padding:22px}}
.worksheet{max-width:900px;margin:36px auto;line-height:1.65}.worksheet h1{font-size:clamp(2rem,5vw,3.2rem);line-height:1.2;margin:10px 0 18px}.worksheet h2{font-size:1.4rem;line-height:1.3;margin:8px 0}.worksheet p{margin:14px 0}.worksheet-eyebrow{color:#b8d997;font-size:.85rem;letter-spacing:.06em}.worksheet-context{display:flex;flex-wrap:wrap;gap:8px;margin:22px 0}.worksheet-context span{padding:5px 12px;border:1px solid #53614c;border-radius:20px;font-size:.9rem}.worksheet-card{padding:28px;border:1px solid #4c5845;border-radius:16px;background:#171d16;margin:26px 0}.worksheet-form fieldset{border:0;padding:0;display:grid;gap:18px;margin-top:22px;min-width:0}.worksheet-form label{display:grid;gap:7px}.worksheet-form input:not([type=checkbox]):not([type=radio]),.worksheet-form textarea{width:100%;box-sizing:border-box;padding:12px;border:1px solid #77816c;border-radius:8px;background:#0f140e;color:#fff;font:inherit}.worksheet-form textarea{min-height:90px;resize:vertical}.worksheet-form .worksheet-check{display:flex;align-items:flex-start;gap:12px}.worksheet-check input{width:20px;height:20px;flex-shrink:0;margin-top:4px;accent-color:#b8d997}.worksheet button,.worksheet-nav button{padding:10px 18px;border:1px solid #77816c;border-radius:8px;background:#26331f;color:#f0eee7;font:inherit;cursor:pointer}.worksheet button[type=submit],.worksheet-nav button[aria-pressed=true]{background:#b8d997;color:#19200f;font-weight:650}.worksheet button:disabled{opacity:.5;cursor:wait}.worksheet-nav{display:flex;flex-wrap:wrap;gap:12px;margin-top:26px}.worksheet-result{display:flex;flex-wrap:wrap;gap:28px;margin:24px 0}.worksheet-result dt{color:#c4ceba;font-size:.9rem}.worksheet-result dd{font-size:1.8rem;margin:3px 0;font-variant-numeric:tabular-nums}.worksheet-result small{font-size:1rem}.worksheet details{margin-top:22px}.worksheet summary{cursor:pointer;text-decoration:underline;text-underline-offset:4px}.worksheet-details dd{margin:0 0 14px;overflow-wrap:anywhere;color:#cfdbc4}.worksheet-details dt{font-weight:650}.worksheet-error{border-left:4px solid #f4ab95;padding:10px 16px;background:#39221c}.worksheet-status{color:#d3e7c2}.worksheet-footnote{border-top:1px solid #53614c;padding-top:20px;color:#c1c8b7}@media(max-width:600px){.worksheet-card{padding:20px}.worksheet-result{display:grid;gap:16px}.worksheet-result dd{font-size:1.5rem}}

.worksheet-reports { margin: 1.25rem 0 2rem; padding: 1.25rem; border: 1px solid #53766b; border-radius: 12px; }
.worksheet-report-actions { display: flex; flex-wrap: wrap; gap: .6rem; margin: .8rem 0; }
.worksheet-report-list { padding-left: 1.2rem; }
.worksheet-report-list li { margin: .6rem 0; }
.worksheet-report-list button { white-space: normal; text-align: left; }
.worksheet-report-view iframe { width: 100%; height: 780px; border: 1px solid #667b72; background: white; border-radius: 6px; margin-top: 1rem; }
.worksheet-fingerprint { overflow-wrap: anywhere; font-family: monospace; }
@media (max-width: 600px) { .worksheet-reports { padding: .7rem; } .worksheet-report-view iframe { height: 680px; } }

.annual-month-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.annual-month-grid label span{font-size:.85rem;color:#c4ceba}.annual-table-wrap{overflow-x:auto}.annual-month-table{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums}.annual-month-table caption{text-align:left;margin:12px 0}.annual-month-table th,.annual-month-table td{padding:10px;text-align:left;border-bottom:1px solid #4c5845}.annual-month-table td{overflow-wrap:anywhere}@media(max-width:700px){.annual-month-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:440px){.annual-month-grid{grid-template-columns:minmax(0,1fr)}.annual-month-table th,.annual-month-table td{padding:8px 4px;font-size:.85rem}}

/* M68 evidence selection follows the existing worksheet form appearance. */
.worksheet-form select{width:100%;min-width:0;box-sizing:border-box;padding:12px;border:1px solid #77816c;border-radius:8px;background:#0f140e;color:#fff;font:inherit}.worksheet-card h3,.worksheet-check{overflow-wrap:anywhere}

/* Corporate coverage uses the existing private workspace controls. */
.corporate-register .coverage-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:16px 0}.corporate-register .coverage-grid button{text-align:left;overflow-wrap:anywhere}.corporate-register .coverage-grid button[aria-pressed=true]{border-color:#b8d997;background:#35472d}.corporate-register h2{margin-top:24px}.corporate-register ul{padding-left:22px}.corporate-register li{margin:8px 0}.coverage-version{display:grid;gap:8px}.coverage-version select{padding:12px;background:#0f140e;color:#fff;border:1px solid #77816c;border-radius:8px;font:inherit;max-width:100%}.corporate-register fieldset{min-width:0}.corporate-register{overflow-wrap:anywhere}@media(max-width:600px){.corporate-register .coverage-grid{grid-template-columns:minmax(0,1fr)}}

.stationary-gas{overflow-wrap:anywhere}.stationary-gas pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:.82rem;line-height:1.6}.stationary-gas table{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums}.stationary-gas th,.stationary-gas td{text-align:left;padding:10px 6px;border-bottom:1px solid #4c5845;overflow-wrap:anywhere}.stationary-gas .worksheet-card>button{margin:6px 8px 6px 0}@media(max-width:440px){.stationary-gas th,.stationary-gas td{padding:8px 3px;font-size:.8rem}}

.mobile-diesel{overflow-wrap:anywhere}.mobile-diesel .coverage-version{grid-template-columns:minmax(0,1fr);min-width:0}.mobile-diesel select{width:100%;min-width:0;box-sizing:border-box}.mobile-diesel pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:.82rem;line-height:1.6}.mobile-diesel table{width:100%;border-collapse:collapse;table-layout:fixed;font-variant-numeric:tabular-nums}.mobile-diesel th,.mobile-diesel td{text-align:left;padding:10px 6px;border-bottom:1px solid #4c5845;overflow-wrap:anywhere}.mobile-diesel .worksheet-card>button{margin:6px 8px 6px 0}@media(max-width:440px){.mobile-diesel th,.mobile-diesel td{padding:8px 3px;font-size:.8rem}}
